// spec: AC #e824b3d3
// seed: tests/seed.user.spec.ts
import path from 'node:path';
import { test, expect } from '@playwright/test';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

test.describe('Экстренные действия', () => {
  test('Экран «עזרה דחופה» и 5 тем первой помощи #e824b3d3 @iphone @prod-safe', async ({ page }) => {
    // 1. Open /home, click the "חירום" button
    await page.goto('/home');
    await page.locator('[aria-label="חירום"]:visible').first().click();
    await expect(page).toHaveURL(/\/emergency$/);
    await expect(page.getByRole('heading', { name: 'עזרה דחופה' }).locator('visible=true')).toBeVisible();
    await expect(page.getByRole('heading', { name: 'קרה משהו בבריכה?' }).locator('visible=true')).toBeVisible();
    await expect(page.getByRole('tab').locator('visible=true')).toHaveCount(0);

    // 2. For each topic: open, verify steps and dial button visibility (never click), go back
    const topics = [
      { name: 'החייאה', slug: 'cpr' },
      { name: 'טביעה', slug: 'drowning' },
      { name: 'דימום', slug: 'bleeding' },
      { name: 'שברים', slug: 'fractures' },
      { name: 'איבוד הכרה', slug: 'unconscious' },
    ];
    for (const topic of topics) {
      await page
        .getByRole('button', { name: new RegExp(`^${topic.name}`) })
        .locator('visible=true')
        .click();
      await expect(page).toHaveURL(new RegExp(`/emergency/${topic.slug}$`));
      await expect(page.getByText('4 שלבים').locator('visible=true')).toBeVisible();
      for (const n of ['1', '2', '3', '4']) {
        await expect(page.getByText(n, { exact: true }).locator('visible=true').first()).toBeVisible();
      }
      await expect(
        page.getByRole('button', { name: 'חיוג למד״א 101' }).locator('visible=true')
      ).toBeVisible();
      await page.getByRole('button', { name: 'חזרה' }).locator('visible=true').click();
      await expect(page).toHaveURL(/\/emergency$/);
    }

    // 3. The MDA link is below the last topic
    const lastTopic = page.getByRole('button', { name: /^איבוד הכרה/ }).locator('visible=true');
    const mdaLink = page.getByRole('button', { name: 'לאתר ולאפליקציה של מד״א' }).locator('visible=true');
    await expect(mdaLink).toBeVisible();
    const topicBox = await lastTopic.boundingBox();
    const linkBox = await mdaLink.boundingBox();
    expect(topicBox).not.toBeNull();
    expect(linkBox).not.toBeNull();
    expect(linkBox!.y).toBeGreaterThan(topicBox!.y + topicBox!.height);
  });
});
